package com.fakrudeenmart.servlet;
import com.fakrudeenmart.model.UserRole; import com.fakrudeenmart.service.AdminService;
import javax.servlet.ServletException; import javax.servlet.http.*; import java.io.IOException;
public class AdminUserEditServlet extends HttpServlet { private AdminService service; public void init(){service=new AdminService();} protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{boolean buyer=req.getRequestURI().contains("/buyers/");long id=AdminServletSupport.id(req.getParameter("id"),"User was not found.");req.setAttribute("user",buyer?service.getBuyer(AdminServletSupport.adminId(req),id):service.getSeller(AdminServletSupport.adminId(req),id));req.setAttribute("profileType",buyer?"buyer":"seller");req.setAttribute("formAction",req.getContextPath()+(buyer?"/admin/buyers/edit?id=":"/admin/sellers/edit?id=")+id);req.getRequestDispatcher("/WEB-INF/views/admin/user-edit.jsp").forward(req,resp);} protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{boolean buyer=req.getRequestURI().contains("/buyers/");try{long id=AdminServletSupport.id(req.getParameter("id"),"User was not found.");if(buyer)service.updateBuyerProfile(AdminServletSupport.adminId(req),id,req.getParameter("fullName"),req.getParameter("email"),req.getParameter("phone"));else service.updateSellerProfile(AdminServletSupport.adminId(req),id,req.getParameter("fullName"),req.getParameter("email"),req.getParameter("phone"));resp.sendRedirect(req.getContextPath()+(buyer?"/admin/buyers/view?id=":"/admin/sellers/view?id=")+id);}catch(Exception e){req.setAttribute("error",AdminServletSupport.message(e,"Unable to update profile."));req.setAttribute("profileType",buyer?"buyer":"seller");req.setAttribute("formAction",req.getContextPath()+(buyer?"/admin/buyers/edit?id=":"/admin/sellers/edit?id=")+req.getParameter("id"));req.getRequestDispatcher("/WEB-INF/views/admin/user-edit.jsp").forward(req,resp);}}}
